const looseManifest: ImportManifest = { rootLabel: '', files: folderManifest.files.map(file => ({ ...file, relativePath: file.filename })) };
const tags = (extra: Record<string, unknown> = {}, identifiers: Record<string, unknown> = {}) => ({ version: 2, title: null, album: null, artists: [], albumArtists: [], label: null, year: null,
    discNumber: null, trackNumber: null, durationMs: null, identifiers: { barcode: null, catalogNumber: null, isrc: null, musicBrainzReleaseId: null, ...identifiers }, flagged: [], ...extra });
