test('the file set is complete only when every manifest slot is ready, and its digest binds identities in manifest order', () => {
    const complete = project([asset(slotB, null), asset(slotA, null), asset('cover', null), asset(`embedded-${slotA}`, null)]);
    const set = importLookupFileSet(complete);
    assert.deepEqual(set.files, [{ slotId: slotA, operationId: '0000000a-0000-4000-8000-0000000000a1', sha256: 'a1'.repeat(32) },
        { slotId: slotB, operationId: '0000000a-0000-4000-8000-0000000000a2', sha256: 'a2'.repeat(32) }]);
    assert.equal(set.complete, true);
    // The order of stored assets and the cover and embedded-artwork slots never change the digest.
    assert.equal(importLookupFileSet(project([asset(slotA, null), asset(slotB, null)])).digest, set.digest);
    // A new upload intent or other bytes in one slot change it.
    assert.notEqual(importLookupFileSet(project([asset(slotA, null, { operationId: '0000000a-0000-4000-8000-0000000000ff' }), asset(slotB, null)])).digest, set.digest);
    assert.notEqual(importLookupFileSet(project([asset(slotA, null, { sha256: 'ff'.repeat(32) }), asset(slotB, null)])).digest, set.digest);
    // A slot without a confirmed file is null, so the set is incomplete.
    for (const state of ['pending', 'unknown', 'failed', 'deleting', 'deleted'] as const) {
        const partial = importLookupFileSet(project([asset(slotA, null), asset(slotB, null, { state })]));
        assert.deepEqual([partial.complete, partial.files[1]], [false, { slotId: slotB, operationId: null, sha256: null }], state);
    }
    assert.equal(importLookupFileSet(project([])).complete, false);
});

test('replaced and removed bound files are stale, while a slot confirmed after the run started is newly known', () => {
    const bound = importLookupFileSet(project([asset(slotA, null), asset(slotB, null, { state: 'pending' })])).files;
    assert.deepEqual(lookupStaleSlots(bound, importLookupFileSet(project([asset(slotA, null), asset(slotB, null)])).files), []);
    assert.deepEqual(lookupStaleSlots(bound, importLookupFileSet(project([asset(slotA, null, { operationId: '0000000a-0000-4000-8000-0000000000ff' }), asset(slotB, null)])).files), [slotA]);
    assert.deepEqual(lookupStaleSlots(bound, importLookupFileSet(project([asset(slotA, null, { sha256: 'ff'.repeat(32) })])).files), [slotA]);
    assert.deepEqual(lookupStaleSlots(bound, importLookupFileSet(project([asset(slotA, null, { state: 'deleting' }), asset(slotB, null)])).files), [slotA]);
    assert.deepEqual(lookupStaleSlots(bound, []), [slotA]);
    // Entries this release cannot read (another release's shape) are skipped rather than failing a removal.
    assert.deepEqual(lookupStaleSlots([null, 'x', 7, { slotId: 5, operationId: 'o' }, { slotId: slotB }, { slotId: slotA, operationId: null }], []), []);
    assert.deepEqual(lookupStaleSlots([null, ...bound], []), [slotA]);
});

test('shared album and album-artist tags plan release searches, and only without usable tags the cleaned folder name, once', () => {
    const album = planImportLookup(project([asset(slotA, tags({ ...shared, artists: ['Per File A'] })), asset(slotB, tags({ ...shared, artists: ['Per File B'] }))]), { folderAvailable: true });
    assert.deepEqual(album.input, { trigger: 'tags', submitted: null });
    // Several files never use per-file artists.
    assert.deepEqual(album.plan.queries, [
        { kind: 'musicBrainzReleaseSearch', query: { release: 'Synthetic Album', artist: 'Synthetic Ensemble' }, basis: 'albumText' },
        { kind: 'musicBrainzReleaseSearch', query: { release: 'Synthetic Album' }, basis: 'albumText' }]);
    // A disagreeing album is no usable tag, so the folder name is used: its format group is dropped and it splits once on " - ".
    const folder = planImportLookup(project([asset(slotA, tags({ album: 'One' })), asset(slotB, tags({ album: 'Two' }))]), { folderAvailable: true });
    assert.deepEqual(folder.input, { trigger: 'folder', submitted: null });
    assert.deepEqual(folder.plan.queries, [
        { kind: 'musicBrainzReleaseSearch', query: { artist: 'Synthetic Artist', release: 'Synthetic Folder' }, basis: 'folder' },
        { kind: 'musicBrainzReleaseSearch', query: { release: 'Synthetic Artist - Synthetic Folder' }, basis: 'folder' }]);
    // Used once per project; files chosen without a folder have none.
    for (const [manifest, folderAvailable] of [[folderManifest, false], [looseManifest, true]] as const) {
        const none = planImportLookup(project([asset(slotA, tags()), asset(slotB, tags())], manifest), { folderAvailable });
        assert.deepEqual([none.input.trigger, none.plan.queries, none.plan.rejected], ['tags', [], 'empty']);
    }
    // Evidence stored before version 2 never reaches lookup, even with an album tag.
    const legacy = { title: 'Legacy', album: 'Synthetic Album', artists: ['Synthetic Ensemble'], year: 2026, trackNumber: 1 };
    assert.equal(planImportLookup(project([asset(slotA, legacy), asset(slotB, legacy)]), { folderAvailable: true }).input.trigger, 'folder');
    // A file without a confirmed upload shares nothing.
    assert.equal(planImportLookup(project([asset(slotA, tags(shared))]), { folderAvailable: false }).plan.queries.length, 0);
});

