    const barcode = planImportLookup(project([asset(slotA, tags({}, { barcode: '0075596050920' })), asset(slotB, tags({}, { barcode: '0075596050920' }))]), { folderAvailable: true });
    assert.deepEqual([barcode.input.trigger, barcode.plan.queries], ['tags', [{ kind: 'musicBrainzReleaseSearch', query: { barcode: '0075596050920' }, basis: 'barcode' }]]);
