    assert.equal(planImportLookup(project([asset(slotA, tags({}, { barcode: '0075596050920' })), asset(slotB, tags())]), { folderAvailable: true }).input.trigger, 'folder');
    const single: ImportManifest = { rootLabel: '', files: [looseManifest.files[0]] };
    const song = planImportLookup(project([asset(slotA, tags({ title: 'Synthetic Song', artists: ['Synthetic Singer', 'Synthetic Guest'] }, { isrc: 'JPY392200483' }))], single), { folderAvailable: true });
